<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useBackendStore,errorText} from '../stores/backend'
import {useResearchStore} from '../stores/research'
import {useCopilotStore} from '../stores/copilot'
import {backendApi,type BackendMessage,type BackendConversation} from '../services/backendApi'
import {messageContext} from '../lib/composerContext'
import {taskLabels} from '../types/copilot'
import Markdown from './ResearchMarkdown.vue'
import Menu from './ConversationMenu.vue'
import DeleteDialog from './ConversationDeleteDialog.vue'
const props=defineProps<{active?:boolean}>(),emit=defineEmits<{restored:[]}>()
const backend=useBackendStore(),research=useResearchStore(),copilot=useCopilotStore(),error=ref(''),notice=ref(''),working=ref(false),preview=ref<{conversation:BackendConversation;messages:BackendMessage[]}|null>(null)
const editing=ref(''),renameTitle=ref(''),renameInput=ref<HTMLInputElement[]>(),deleting=ref<BackendConversation|null>(null)
let timer:ReturnType<typeof setTimeout>|undefined,previewVersion=0,disposed=false
const empty=computed(()=>backend.historyQuery?'没有搜索结果。':backend.historyState==='deleted'?'最近删除为空。':backend.historyState==='archived'?'没有归档对话。':'没有历史对话。')
const spaceName=(id?:string|null)=>{const s=research.sessions.find(s=>s.id===id);return s?.customTitle||s?.title||(id==='default'?'默认空间':id?'此浏览器未保存的空间':'历史记录 · 空间未确认')}
function dateText(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?value:new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(date)}
async function load(more=false){error.value='';try{await backend.listHistory(more?backend.historyPage+1:0)}catch(e){error.value=errorText(e)}}
watch(()=>[backend.historyQuery,backend.historyScope,backend.historyState,backend.spaceId],()=>{previewVersion++;preview.value=null;clearTimeout(timer);timer=setTimeout(()=>void load(),300)})
async function inspect(c:BackendConversation){const version=++previewVersion;error.value='';try{const data=await backendApi.conversation(c.id);if(!disposed&&version===previewVersion)preview.value={conversation:data.conversation,messages:data.messages}}catch(e){if(version===previewVersion)error.value=errorText(e)}}
async function rename(c:BackendConversation){if(working.value)return;if(!renameTitle.value.trim()){error.value='标题不能为空。';return}working.value=true;try{await backendApi.renameConversation(c.id,renameTitle.value.trim(),c.revision);editing.value='';await load();notice.value='对话名称已保存'}catch(e){error.value=errorText(e)}finally{working.value=false}}
async function action(c:BackendConversation,id:string){error.value='';notice.value='';if(id==='rename'){editing.value=c.id;renameTitle.value=c.title;await nextTick();renameInput.value?.[0]?.focus();return}if(id==='delete'){deleting.value=c;return}working.value=true;try{await backend.manageConversation(c,id);preview.value=null;notice.value=id==='restore'?'对话已恢复':id==='archive'?'对话已归档':id==='unarchive'?'已取消归档':id==='pin'?'对话已置顶':'已取消置顶'}catch(e){error.value=errorText(e)}finally{working.value=false}}
async function remove(){if(!deleting.value||working.value)return;working.value=true;try{await backend.manageConversation(deleting.value,'delete');previewVersion++;preview.value=null;deleting.value=null;notice.value='已移至最近删除'}catch(e){error.value=errorText(e)}finally{working.value=false}}
function items(c:BackendConversation){return [{id:'rename',label:'重命名'},{id:c.pinnedAt?'unpin':'pin',label:c.pinnedAt?'取消置顶':'置顶'},{id:c.archivedAt?'unarchive':'archive',label:c.archivedAt?'取消归档':'归档'},{id:'delete',label:'移至最近删除'}]}
async function associate(){const item=preview.value;if(!item)return;try{item.conversation=await backendApi.associateConversation(item.conversation.id,backend.spaceId);await load();notice.value='已关联当前研究空间'}catch(e){error.value=errorText(e)}}
async function restore(){const c=preview.value?.conversation;if(!c)return;error.value='';try{if(copilot.busy||backend.busy)throw new Error('请先停止当前 AI 任务。');if(c.archivedAt)throw new Error('请先取消归档，再继续对话。');if(c.workspaceId&&c.workspaceId!==backend.spaceId){if(c.workspaceId!=='default'&&!research.sessions.some(s=>s.id===c.workspaceId))throw new Error('原研究空间不在此浏览器，当前仅提供历史预览。');if(c.workspaceId!=='default')research.loadSession(c.workspaceId);await backend.switchWorkspace(c.workspaceId)}else if(!c.workspaceId)throw new Error('此历史对话的空间归属未确认，暂仅提供预览。');await backend.openConversation(c.id);preview.value=null;emit('restored')}catch(e){error.value=errorText(e)}}
async function fresh(){try{await backend.newConversation();emit('restored')}catch(e){error.value=errorText(e)}}
onMounted(()=>void load());watch(()=>props.active,value=>{if(value)void load()});onBeforeUnmount(()=>{disposed=true;previewVersion++;clearTimeout(timer)})
</script>
<template><section class="copilot-history-panel" aria-label="历史对话与科研分析"><div class="button-row"><h3>历史对话</h3><button class="text-button" @click="fresh">新建对话</button><button class="text-button" :disabled="backend.historyLoading" @click="load()">刷新</button></div>
<label>搜索对话<input v-model="backend.historyQuery" type="search" maxlength="200" placeholder="搜索对话标题或消息内容…"/></label><div class="history-filters"><label>范围<select v-model="backend.historyScope"><option value="current">当前研究空间</option><option value="all">全部研究空间</option></select></label><label>状态<select v-model="backend.historyState"><option value="active">活跃对话</option><option value="archived">已归档</option><option value="deleted">最近删除</option></select></label></div>
<p v-if="backend.historyLoading" role="status" class="settings-hint">正在读取后端记录…</p><p v-if="error||backend.historyError" role="alert" class="form-error">{{error||backend.historyError}}</p><p v-if="notice" role="status" class="settings-hint">{{notice}}</p><p v-if="!backend.historyLoading&&!backend.conversationHistory.length" class="settings-hint">{{empty}}</p>
<div v-for="c in backend.conversationHistory" :key="c.id" class="history-row" :class="{current:c.id===backend.conversationId}"><form v-if="editing===c.id" class="history-rename" @submit.prevent="rename(c)"><input ref="renameInput" v-model="renameTitle" :aria-label="'重命名 '+c.title" maxlength="180" @keydown.esc.prevent="editing=''"/><small>Enter 保存 · Escape 取消；离开输入框不会自动保存</small><button type="submit" class="text-button" :disabled="working">保存</button><button type="button" class="text-button" @click="editing=''">取消</button></form><template v-else><button class="history-conversation" :disabled="!!c.deletedAt" :aria-current="c.id===backend.conversationId?'true':undefined" @click="inspect(c)"><strong>{{c.pinnedAt?'置顶 · ':''}}{{c.title}}</strong><small>{{spaceName(c.workspaceId)}} · {{c.deletedAt?'删除于 '+dateText(c.deletedAt):dateText(c.updatedAt)}}</small></button><button v-if="c.deletedAt" class="text-button" :disabled="working" @click="action(c,'restore')">恢复</button><Menu v-else :title="c.title" :items="items(c)" @select="action(c,$event)"/></template></div>
<button v-if="backend.conversationHistory.length<backend.historyTotal" class="text-button" :disabled="backend.historyLoading" @click="load(true)">加载更多会话</button>
<section v-if="preview" class="history-preview"><p class="settings-hint">历史预览不改变当前引用范围或草稿。</p><button v-if="!preview.conversation.workspaceId" class="secondary-button" @click="associate">将此旧对话关联当前研究空间</button><button class="secondary-button" :disabled="copilot.busy||backend.busy||!!preview.conversation.archivedAt||!preview.conversation.workspaceId" @click="restore">恢复此会话 · 不自动引用旧 PDF</button><article v-for="message in preview.messages" :key="message.id"><small>{{message.role==='user'?'你':'Orbit'}}</small><Markdown :text="messageContext(message.content).text"/></article><button class="text-button" @click="previewVersion++;preview=null">关闭预览</button></section>
<h4>当前会话科研分析</h4><p v-if="!copilot.history.length" class="settings-hint">切换会话可查看对应分析；独立笔记保留在空间笔记中。</p><button v-for="analysis in copilot.history" :key="analysis.id" class="history-conversation" :disabled="copilot.busy" @click="copilot.show(analysis);emit('restored')"><strong>{{taskLabels[analysis.task]}}</strong><small>{{analysis.sources.map(s=>s.title).join(' / ')}}</small></button>
<DeleteDialog v-if="deleting" :title="deleting.title" :busy="working" :error="error" @close="!working&&(deleting=null)" @confirm="remove"/></section></template>
<style scoped>.history-filters{display:flex;gap:8px;margin:10px 0}.history-filters label{min-width:0;flex:1;font-size:12px}.history-filters select{width:100%;padding:6px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text)}.history-row{display:flex;align-items:center;border-radius:9px;margin:3px 0}.history-row.current{background:var(--purple-soft)}.history-row .history-conversation{flex:1;min-width:0;margin:0}.history-row strong,.history-row small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.history-row small{font-size:11px}.history-rename{width:100%;padding:8px}.history-rename small{font-size:11px;color:var(--muted)}</style>
